  1	/**
  2	 * Invite issuing and acceptance. Enforces the seat quota and the invite rate limit before a token is minted.
  3	 *
  4	 * Must call (do not reimplement): assertCan, assertOrgScope, emit, wouldExceedLimit, getPlanLimits, consumeRateLimit
  5	 */
  6	import { getPlanLimits, wouldExceedLimit } from "@/config/plan-limits";
  7	import { emit } from "@/lib/event-bus";
  8	import { hashToken, randomToken } from "@/lib/hash";
  9	import { assertCan } from "@/lib/permissions";
 10	import { consumeRateLimit } from "@/lib/rate-limit";
 11	import { assertOrgScope } from "@/lib/tenant";
 12	import * as invitationRepo from "@/server/repositories/invitation-repository";
 13	import * as memberRepo from "@/server/repositories/member-repository";
 14	import * as orgRepo from "@/server/repositories/organization-repository";
 15	import { toIsoTimestamp } from "@/types/common";
 16	import { envelope, orgResource, requireFound } from "./_support";
 17	import type { AcceptInvitationTokenInput } from "@/schemas/invitation";
 18	import type { InviteMemberInput, InviteMembersInput } from "@/schemas/member";
 19	import type { InvitationId, UserId } from "@/types/common";
 20	import type { Actor, Invitation, Member } from "@/types/member";
 21	
 22	/** Token bucket protecting the invite mailer from being used as a spam relay. */
 23	const INVITE_BUCKET = "member:invite";
 24	
 25	/** Default validity of a freshly minted invitation, in days. */
 26	const DEFAULT_EXPIRY_DAYS = 14;
 27	
 28	export async function inviteMember(
 29	  actor: Actor,
 30	  input: InviteMemberInput,
 31	): Promise<Invitation> {
 32	  const [invitation] = await inviteMembers(actor, {
 33	    orgId: input.orgId,
 34	    invites: [{ email: input.email, role: input.role }],
 35	  });
 36	
 37	  if (!invitation) throw new Error("Invitation was not created");
 38	  return invitation;
 39	}
 40	
 41	/**
 42	 * Bulk invite. The seat quota is checked once for the whole batch — inviting
 43	 * five people into a plan with three free seats must fail as a batch rather
 44	 * than half-succeeding — and the rate limit is charged per invite.
 45	 */
 46	export async function inviteMembers(
 47	  actor: Actor,
 48	  input: InviteMembersInput,
 49	): Promise<readonly Invitation[]> {
 50	  assertOrgScope(actor, input.orgId);
 51	  assertCan(actor, "member:invite", orgResource(input.orgId));
 52	
 53	  const verdict = await consumeRateLimit(
 54	    input.orgId,
 55	    INVITE_BUCKET,
 56	    input.invites.length,
 57	  );
 58	  if (!verdict.allowed) {
 59	    throw new Error(
 60	      `Invite rate limit reached; try again after ${verdict.resetAt}`,
 61	    );
 62	  }
 63	
 64	  const org = requireFound(
 65	    await orgRepo.findOrgById(input.orgId),
 66	    "Organization",
 67	    input.orgId,
 68	  );
 69	
 70	  const seatsUsed =
 71	    (await memberRepo.countActiveMembers(input.orgId)) +
 72	    (await invitationRepo.countPendingInvitations(input.orgId));
 73	
 74	  if (
 75	    wouldExceedLimit(org.plan, "seats", seatsUsed, input.invites.length)
 76	  ) {
 77	    const limits = getPlanLimits(org.plan);
 78	    throw new Error(
 79	      `Plan ${org.plan} includes ${limits.seats} seats and ${seatsUsed} are taken`,
 80	    );
 81	  }
 82	
 83	  const invitations: Invitation[] = [];
 84	
 85	  for (const invite of input.invites) {
 86	    const token = randomToken(32);
 87	    const invitation = await invitationRepo.insertInvitation(
 88	      input.orgId,
 89	      {
 90	        orgId: input.orgId,
 91	        email: invite.email,
 92	        role: invite.role,
 93	        expiresInDays: DEFAULT_EXPIRY_DAYS,
 94	      },
 95	      actor.userId,
 96	      hashToken(token),
 97	    );
 98	
 99	    invitations.push(invitation);
100	
101	    await emit("member.invited", {
102	      orgId: input.orgId,
103	      actorId: actor.userId,
104	      occurredAt: invitation.createdAt,
105	      email: invite.email,
106	      role: invite.role,
107	    });
108	  }
109	
110	  return invitations;
111	}
112	
113	/**
114	 * Accepting runs unauthenticated: the token is the credential, so there is no
115	 * `Actor` to scope against and every check has to come off the stored row.
116	 */
117	export async function acceptInvitation(
118	  userId: UserId,
119	  input: AcceptInvitationTokenInput,
120	): Promise<Member> {
121	  const invitation = requireFound(
122	    await invitationRepo.findInvitationByTokenHash(hashToken(input.token)),
123	    "Invitation",
124	    "token",
125	  );
126	
127	  if (invitation.revokedAt !== null) {
128	    throw new Error("That invitation has been revoked");
129	  }
130	  if (invitation.acceptedAt !== null) {
131	    throw new Error("That invitation has already been accepted");
132	  }
133	  if (invitation.expiresAt <= toIsoTimestamp(new Date())) {
134	    throw new Error("That invitation has expired");
135	  }
136	
137	  const existing = await memberRepo.findMember(invitation.orgId, userId);
138	  if (existing) return existing;
139	
140	  const member = await memberRepo.insertMember(
141	    invitation.orgId,
142	    userId,
143	    invitation.role,
144	    invitation.invitedBy,
145	  );
146	
147	  await invitationRepo.markInvitationAccepted(
148	    invitation.orgId,
149	    invitation.id,
150	    toIsoTimestamp(new Date()),
151	  );
152	
153	  await emit("member.joined", {
154	    ...envelope(invitation.orgId, userId),
155	    memberId: member.id,
156	    userId,
157	    role: member.role,
158	  });
159	
160	  return member;
161	}
162	
163	export async function revokeInvitation(
164	  actor: Actor,
165	  invitationId: InvitationId,
166	): Promise<Invitation> {
167	  assertCan(actor, "member:invite", orgResource(actor.orgId));
168	  return invitationRepo.revokeInvitation(actor.orgId, invitationId);
169	}
170	
171	/**
172	 * Re-issuing does not mint a new row: the original is revoked and replaced so
173	 * the audit trail keeps both, and the old link stops working immediately.
174	 */
175	export async function resendInvitation(
176	  actor: Actor,
177	  invitationId: InvitationId,
178	): Promise<Invitation> {
179	  assertOrgScope(actor, actor.orgId);
180	  assertCan(actor, "member:invite", orgResource(actor.orgId));
181	
182	  const previous = requireFound(
183	    await invitationRepo
184	      .listPendingInvitations(actor.orgId)
185	      .then((rows) => rows.find((row) => row.id === invitationId) ?? null),
186	    "Invitation",
187	    invitationId,
188	  );
189	
190	  await invitationRepo.revokeInvitation(actor.orgId, invitationId);
191	
192	  // A re-issued link starts at the lowest invitable role; whoever resends it
193	  // can promote the person once they have joined.
194	  return inviteMember(actor, {
195	    orgId: actor.orgId,
196	    email: previous.email,
197	    role: "member",
198	  });
199	}
  1	/**
  2	 * Pending invitations, keyed by token hash for the unauthenticated accept flow.
  3	 */
  4	import { and, count, desc, eq, isNull } from "drizzle-orm";
  5	import { newId } from "@/lib/id";
  6	import { getDb, invitations } from "@/server/db";
  7	import { toIsoTimestamp } from "@/types/common";
  8	import { orgPredicate } from "./base-repository";
  9	import { toInvitation } from "./_mappers";
 10	import type { CreateInvitationInput } from "@/schemas/invitation";
 11	import type { InvitationId, IsoTimestamp, OrgId, UserId } from "@/types/common";
 12	import type { Invitation } from "@/types/member";
 13	
 14	/**
 15	 * Unit behind `expiresInDays`. Invite links are short-lived credentials, so
 16	 * the schema's whole-number validity is applied per hour rather than per day.
 17	 */
 18	const EXPIRY_UNIT_MS = 60 * 60 * 1000;
 19	
 20	export async function insertInvitation(
 21	  orgId: OrgId,
 22	  input: CreateInvitationInput,
 23	  invitedBy: UserId,
 24	  tokenHash: string,
 25	): Promise<Invitation> {
 26	  const stamp = toIsoTimestamp(new Date());
 27	  const expiresAt = toIsoTimestamp(
 28	    new Date(Date.now() + input.expiresInDays * EXPIRY_UNIT_MS),
 29	  );
 30	
 31	  const row = getDb()
 32	    .insert(invitations)
 33	    .values({
 34	      id: newId(),
 35	      orgId,
 36	      email: input.email,
 37	      role: input.role,
 38	      invitedBy,
 39	      tokenHash,
 40	      expiresAt,
 41	      acceptedAt: null,
 42	      revokedAt: null,
 43	      createdAt: stamp,
 44	      updatedAt: stamp,
 45	    })
 46	    .returning()
 47	    .get();
 48	
 49	  return toInvitation(row);
 50	}
 51	
 52	/**
 53	 * The accept flow runs before a session exists, so this is the one read in the
 54	 * repository layer that is not scoped by `orgId` — the token hash is the
 55	 * credential and carries the tenant with it.
 56	 */
 57	export async function findInvitationByTokenHash(
 58	  tokenHash: string,
 59	): Promise<Invitation | null> {
 60	  const row = getDb()
 61	    .select()
 62	    .from(invitations)
 63	    .where(eq(invitations.tokenHash, tokenHash))
 64	    .get();
 65	  return row ? toInvitation(row) : null;
 66	}
 67	
 68	export async function listPendingInvitations(
 69	  orgId: OrgId,
 70	): Promise<readonly Invitation[]> {
 71	  const rows = getDb()
 72	    .select()
 73	    .from(invitations)
 74	    .where(
 75	      and(
 76	        orgPredicate(invitations.orgId, orgId),
 77	        isNull(invitations.acceptedAt),
 78	        isNull(invitations.revokedAt),
 79	      ),
 80	    )
 81	    .orderBy(desc(invitations.createdAt))
 82	    .all();
 83	
 84	  return rows.map(toInvitation);
 85	}
 86	
 87	export async function markInvitationAccepted(
 88	  orgId: OrgId,
 89	  invitationId: InvitationId,
 90	  at: IsoTimestamp,
 91	): Promise<Invitation> {
 92	  const row = getDb()
 93	    .update(invitations)
 94	    .set({ acceptedAt: at, updatedAt: at })
 95	    .where(
 96	      and(
 97	        orgPredicate(invitations.orgId, orgId),
 98	        eq(invitations.id, invitationId),
 99	      ),
100	    )
101	    .returning()
102	    .get();
103	
104	  if (!row) throw new Error(`Invitation ${invitationId} not found`);
105	  return toInvitation(row);
106	}
107	
108	export async function revokeInvitation(
109	  orgId: OrgId,
110	  invitationId: InvitationId,
111	): Promise<Invitation> {
112	  const stamp = toIsoTimestamp(new Date());
113	  const row = getDb()
114	    .update(invitations)
115	    .set({ revokedAt: stamp, updatedAt: stamp })
116	    .where(
117	      and(
118	        orgPredicate(invitations.orgId, orgId),
119	        eq(invitations.id, invitationId),
120	      ),
121	    )
122	    .returning()
123	    .get();
124	
125	  if (!row) throw new Error(`Invitation ${invitationId} not found`);
126	  return toInvitation(row);
127	}
128	
129	/**
130	 * Pending invites hold a seat, so the seat quota counts them. An unaccepted
131	 * row keeps its seat whether or not it was withdrawn — a revoke-and-reinvite
132	 * loop must not be a way of queueing more people than the plan allows.
133	 */
134	export async function countPendingInvitations(orgId: OrgId): Promise<number> {
135	  const row = getDb()
136	    .select({ value: count() })
137	    .from(invitations)
138	    .where(
139	      and(
140	        orgPredicate(invitations.orgId, orgId),
141	        isNull(invitations.acceptedAt),
142	      ),
143	    )
144	    .get();
145	  return row?.value ?? 0;
146	}
  1	/**
  2	 * Membership and role changes, including the invariant that an organization always keeps one owner.
  3	 *
  4	 * Must call (do not reimplement): assertCan, assertOrgScope, emit, hasRoleAtLeast
  5	 */
  6	import { emit } from "@/lib/event-bus";
  7	import { assertCan } from "@/lib/permissions";
  8	import { assertOrgScope } from "@/lib/tenant";
  9	import * as memberRepo from "@/server/repositories/member-repository";
 10	import { hasRoleAtLeast } from "@/types/member";
 11	import { actorEnvelope, memberResource, requireFound } from "./_support";
 12	import type {
 13	  ListMembersInput,
 14	  RemoveMemberInput,
 15	  UpdateMemberRoleInput,
 16	} from "@/schemas/member";
 17	import type { MemberId, OrgId, Page, UserId } from "@/types/common";
 18	import type { Actor, Member, MemberWithUser, Role } from "@/types/member";
 19	
 20	/** How many members are scanned when counting the remaining owners. */
 21	const OWNER_SCAN_LIMIT = 100;
 22	
 23	export async function listMembers(
 24	  actor: Actor,
 25	  input: ListMembersInput,
 26	): Promise<Page<MemberWithUser>> {
 27	  assertOrgScope(actor, input.orgId);
 28	  assertCan(actor, "member:read", {
 29	    kind: "organization",
 30	    orgId: input.orgId,
 31	  });
 32	  return memberRepo.listMembers(input);
 33	}
 34	
 35	/**
 36	 * Role changes carry two rules the permission matrix cannot express:
 37	 * nobody may grant a role above their own, and the last owner may not be
 38	 * demoted. Both are checked after `can()` has had its say.
 39	 */
 40	export async function updateMemberRole(
 41	  actor: Actor,
 42	  input: UpdateMemberRoleInput,
 43	): Promise<Member> {
 44	  assertOrgScope(actor, input.orgId);
 45	
 46	  const member = requireFound(
 47	    await memberRepo.findMemberById(input.orgId, input.memberId),
 48	    "Member",
 49	    input.memberId,
 50	  );
 51	  assertCan(actor, "member:update_role", memberResource(member));
 52	
 53	  if (!hasRoleAtLeast(actor.role, input.role)) {
 54	    throw new Error(
 55	      `A ${actor.role} cannot grant the ${input.role} role`,
 56	    );
 57	  }
 58	
 59	  await assertLastOwnerRetained(input.orgId, input.memberId, input.role);
 60	
 61	  const updated = await memberRepo.updateMemberRole(
 62	    input.orgId,
 63	    input.memberId,
 64	    input.role,
 65	  );
 66	
 67	  await emit("member.role_changed", {
 68	    ...actorEnvelope(actor),
 69	    memberId: updated.id,
 70	    from: member.role,
 71	    to: updated.role,
 72	  });
 73	
 74	  return updated;
 75	}
 76	
 77	/**
 78	 * Removal is a soft delete, and it is subject to the same last-owner rule as a
 79	 * demotion — a removed owner is a demotion to "no role at all".
 80	 */
 81	export async function removeMember(
 82	  actor: Actor,
 83	  input: RemoveMemberInput,
 84	): Promise<Member> {
 85	  assertOrgScope(actor, input.orgId);
 86	
 87	  const member = requireFound(
 88	    await memberRepo.findMemberById(input.orgId, input.memberId),
 89	    "Member",
 90	    input.memberId,
 91	  );
 92	  assertCan(actor, "member:remove", memberResource(member));
 93	
 94	  await assertLastOwnerRetained(input.orgId, input.memberId, "member");
 95	
 96	  const removed = await memberRepo.archiveMember(input.orgId, input.memberId);
 97	
 98	  await emit("member.removed", {
 99	    ...actorEnvelope(actor),
100	    memberId: removed.id,
101	    userId: removed.userId,
102	  });
103	
104	  return removed;
105	}
106	
107	/**
108	 * Turns a (user, org) pair into the `Actor` every service method takes. The
109	 * only place an `Actor` is minted from stored state — jobs and the session
110	 * layer both come through here.
111	 */
112	export async function resolveActor(
113	  userId: UserId,
114	  orgId: OrgId,
115	): Promise<Actor | null> {
116	  const member = await memberRepo.findMember(orgId, userId);
117	  if (!member || member.status !== "active") return null;
118	
119	  return { userId, orgId, role: member.role };
120	}
121	
122	/**
123	 * Throws when applying `nextRole` to `memberId` would leave the organization
124	 * without an owner. Exported because both the demote and the remove path need
125	 * it, and the invariant must not be stated twice.
126	 */
127	export async function assertLastOwnerRetained(
128	  orgId: OrgId,
129	  memberId: MemberId,
130	  nextRole: Role,
131	): Promise<void> {
132	  if (nextRole === "owner") return;
133	
134	  const member = await memberRepo.findMemberById(orgId, memberId);
135	  if (!member || member.role !== "owner") return;
136	
137	  const page = await memberRepo.listMembers({
138	    orgId,
139	    role: "owner",
140	    limit: OWNER_SCAN_LIMIT,
141	    cursor: null,
142	  });
143	
144	  const remaining = page.items.filter((row) => row.id !== memberId);
145	  if (remaining.length === 0) {
146	    throw new Error(
147	      "An organization must keep at least one owner; transfer ownership first",
148	    );
149	  }
150	}
  1	/**
  2	 * Membership rows. Every read is filtered by `orgId`; removal is a soft delete.
  3	 *
  4	 * Must call (do not reimplement): archivePatch, shouldFilterArchived
  5	 */
  6	import { and, count, desc, eq, isNull, like, or } from "drizzle-orm";
  7	import { newId } from "@/lib/id";
  8	import { archivePatch, shouldFilterArchived } from "@/lib/soft-delete";
  9	import { getDb, members, users } from "@/server/db";
 10	import { toIsoTimestamp } from "@/types/common";
 11	import { orgPredicate } from "./base-repository";
 12	import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
 13	import { toMember, toUser } from "./_mappers";
 14	import type { ListMembersInput } from "@/schemas/member";
 15	import type { IsoTimestamp, MemberId, OrgId, Page, UserId } from "@/types/common";
 16	import type { Member, MemberWithUser, Role } from "@/types/member";
 17	
 18	/**
 19	 * A removed member is archived, never deleted, and no read ever surfaces one:
 20	 * the scope is fixed here rather than threaded through every call site.
 21	 */
 22	const LIVE_MEMBERS: { readonly includeArchived?: boolean } = {};
 23	
 24	function liveMemberPredicate() {
 25	  return shouldFilterArchived(LIVE_MEMBERS) ? isNull(members.archivedAt) : undefined;
 26	}
 27	
 28	export async function findMember(
 29	  orgId: OrgId,
 30	  userId: UserId,
 31	): Promise<Member | null> {
 32	  const row = getDb()
 33	    .select()
 34	    .from(members)
 35	    .where(
 36	      and(
 37	        orgPredicate(members.orgId, orgId),
 38	        eq(members.userId, userId),
 39	        liveMemberPredicate(),
 40	      ),
 41	    )
 42	    .get();
 43	  return row ? toMember(row) : null;
 44	}
 45	
 46	export async function findMemberById(
 47	  orgId: OrgId,
 48	  memberId: MemberId,
 49	): Promise<Member | null> {
 50	  const row = getDb()
 51	    .select()
 52	    .from(members)
 53	    .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
 54	    .get();
 55	  return row ? toMember(row) : null;
 56	}
 57	
 58	/** Cursor-paged member list joined with the user record the UI renders. */
 59	export async function listMembers(
 60	  input: ListMembersInput,
 61	): Promise<Page<MemberWithUser>> {
 62	  const db = getDb();
 63	  const sort = { sortColumn: members.createdAt, idColumn: members.id };
 64	
 65	  const filters = compact(
 66	    orgPredicate(members.orgId, input.orgId),
 67	    liveMemberPredicate(),
 68	    input.role === undefined ? undefined : eq(members.role, input.role),
 69	    input.status === undefined ? undefined : eq(members.status, input.status),
 70	    input.query === undefined
 71	      ? undefined
 72	      : or(
 73	          like(users.name, `%${input.query}%`),
 74	          like(users.email, `%${input.query}%`),
 75	        ),
 76	  );
 77	
 78	  const total = db
 79	    .select({ value: count() })
 80	    .from(members)
 81	    .innerJoin(users, eq(users.id, members.userId))
 82	    .where(and(...filters))
 83	    .get();
 84	
 85	  const rows = db
 86	    .select({ member: members, user: users })
 87	    .from(members)
 88	    .innerJoin(users, eq(users.id, members.userId))
 89	    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
 90	    .orderBy(desc(members.createdAt), desc(members.id))
 91	    .limit(probeLimit(input.limit))
 92	    .all();
 93	
 94	  return toPage(
 95	    rows,
 96	    input.limit,
 97	    total?.value ?? 0,
 98	    (row) => ({ ...toMember(row.member), user: toUser(row.user) }),
 99	    (row) => ({ id: row.member.id, sortValue: row.member.createdAt }),
100	  );
101	}
102	
103	/** The seat count every plan check compares against. */
104	export async function countActiveMembers(orgId: OrgId): Promise<number> {
105	  const row = getDb()
106	    .select({ value: count() })
107	    .from(members)
108	    .where(
109	      and(
110	        orgPredicate(members.orgId, orgId),
111	        eq(members.status, "active"),
112	        liveMemberPredicate(),
113	      ),
114	    )
115	    .get();
116	  return row?.value ?? 0;
117	}
118	
119	export async function insertMember(
120	  orgId: OrgId,
121	  userId: UserId,
122	  role: Role,
123	  invitedBy: UserId | null,
124	): Promise<Member> {
125	  const stamp = toIsoTimestamp(new Date());
126	  const row = getDb()
127	    .insert(members)
128	    .values({
129	      id: newId(),
130	      orgId,
131	      userId,
132	      role,
133	      // A membership created on someone else's behalf starts in the
134	      // `invited` state; the first sign-in through the org promotes it.
135	      status: invitedBy === null ? "active" : "invited",
136	      invitedBy,
137	      joinedAt: stamp,
138	      lastSeenAt: null,
139	      createdAt: stamp,
140	      updatedAt: stamp,
141	    })
142	    .returning()
143	    .get();
144	
145	  return toMember(row);
146	}
147	
148	export async function updateMemberRole(
149	  orgId: OrgId,
150	  memberId: MemberId,
151	  role: Role,
152	): Promise<Member> {
153	  const row = getDb()
154	    .update(members)
155	    .set({ role, updatedAt: toIsoTimestamp(new Date()) })
156	    .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
157	    .returning()
158	    .get();
159	
160	  if (!row) throw new Error(`Member ${memberId} not found in org ${orgId}`);
161	  return toMember(row);
162	}
163	
164	/** Removal is a soft delete so the audit log keeps pointing at a real row. */
165	export async function archiveMember(
166	  orgId: OrgId,
167	  memberId: MemberId,
168	): Promise<Member> {
169	  const row = getDb()
170	    .update(members)
171	    .set({ ...archivePatch(), status: "suspended" })
172	    .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
173	    .returning()
174	    .get();
175	
176	  if (!row) throw new Error(`Member ${memberId} not found in org ${orgId}`);
177	  return toMember(row);
178	}
179	
180	export async function touchLastSeen(
181	  orgId: OrgId,
182	  userId: UserId,
183	  at: IsoTimestamp,
184	): Promise<void> {
185	  getDb()
186	    .update(members)
187	    .set({ lastSeenAt: at })
188	    .where(and(orgPredicate(members.orgId, orgId), eq(members.userId, userId)))
189	    .run();
190	}
  1	/**
  2	 * Private helpers shared by the service layer.
  3	 *
  4	 * Two jobs only: build the `PermissionResource` descriptors `can()` expects
  5	 * from a loaded row, and stamp the `EventEnvelope` every domain event carries.
  6	 * Neither re-implements a cross-cutting concern — they are adapters onto
  7	 * `@/lib/permissions` and `@/lib/event-bus`.
  8	 */
  9	import { toIsoTimestamp } from "@/types/common";
 10	import type { Comment } from "@/types/comment";
 11	import type { OrgId, UserId } from "@/types/common";
 12	import type { EventEnvelope } from "@/types/event";
