p='src/server/services/invitation-service.ts'
s=open(p).read()
i=s.index('export async function inviteMember(')
head=s[:i]
head=head.replace('''import * as orgRepo from "@/server/repositories/organization-repository";
''','''import * as orgRepo from "@/server/repositories/organization-repository";
import * as userRepo from "@/server/repositories/user-repository";
''')
head=head.replace('''import { envelope, orgResource, requireFound } from "./_support";''','''import { envelope, NotFoundError, orgResource, requireFound } from "./_support";''')
head=head.replace('''import type { InvitationId, UserId } from "@/types/common";
import type { Actor, Invitation, Member } from "@/types/member";
''','''import type { InvitationId, OrgId, UserId } from "@/types/common";
import type { Actor, Invitation, Member } from "@/types/member";
import type { Organization } from "@/types/organization";
''')
body = r'''/** One address to invite and the role it is offered. */
type InviteRequest = InviteMembersInput["invites"][number];

/** Addresses are compared without regard to letter case, everywhere. */
function addressKey(email: string): string {
  return email.trim().toLowerCase();
}

/** An archived organization has been deleted as far as invitations go. */
async function requireLiveOrg(orgId: OrgId): Promise<Organization> {
  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  if (org.archivedAt !== null) throw new NotFoundError("Organization", orgId);
  return org;
}

export async function inviteMember(
  actor: Actor,
  input: InviteMemberInput,
): Promise<Invitation> {
  const [invitation] = await inviteMembers(actor, {
    orgId: input.orgId,
    invites: [{ email: input.email, role: input.role }],
  });

  if (!invitation) throw new Error("Invitation was not created");
  return invitation;
}

/**
 * Bulk invite. The seat quota is checked once for the whole batch — inviting
 * five people into a plan with three free seats must fail as a batch rather
 * than half-succeeding — and the rate limit is charged per invite.
 */
export async function inviteMembers(
  actor: Actor,
  input: InviteMembersInput,
): Promise<readonly Invitation[]> {
  return issueInvitations(actor, input.orgId, input.invites, null);
}

/**
 * The single path that mints invitations. Every refusal — permission, rate
 * limit, a duplicate address, the seat quota — happens before the first row
 * is written, so a refused batch leaves nothing behind.
 *
 * `replacing` is the invitation a re-send withdraws: it is ignored by the
 * duplicate and seat checks (its seat passes to the replacement) and is only
 * revoked once the replacement is known to be allowed.
 */
async function issueInvitations(
  actor: Actor,
  orgId: OrgId,
  invites: readonly InviteRequest[],
  replacing: Invitation | null,
): Promise<readonly Invitation[]> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "member:invite", orgResource(orgId));

  const verdict = await consumeRateLimit(orgId, INVITE_BUCKET, invites.length);
  if (!verdict.allowed) {
    throw new Error(
      `Invite rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const org = await requireLiveOrg(orgId);

  const requested = new Set<string>();
  for (const invite of invites) {
    const key = addressKey(invite.email);
    if (requested.has(key)) {
      throw new Error(`${invite.email} is named more than once in this batch`);
    }
    requested.add(key);
  }

  const memberAddresses = new Set(
    (await memberRepo.listCurrentMemberEmails(orgId)).map(addressKey),
  );
  const pendingAddresses = new Set(
    (await invitationRepo.listPendingInvitations(orgId))
      .filter((pending) => pending.id !== replacing?.id)
      .map((pending) => addressKey(pending.email)),
  );

  for (const invite of invites) {
    const key = addressKey(invite.email);
    if (memberAddresses.has(key)) {
      throw new Error(
        `${invite.email} already belongs to a member of this organization`,
      );
    }
    if (pendingAddresses.has(key)) {
      throw new Error(`${invite.email} already has a pending invitation`);
    }
  }

  const seatsUsed =
    (await memberRepo.countActiveMembers(orgId)) +
    (await invitationRepo.countPendingInvitations(
      orgId,
      replacing?.id ?? null,
    ));

  if (wouldExceedLimit(org.plan, "seats", seatsUsed, invites.length)) {
    const limits = getPlanLimits(org.plan);
    throw new Error(
      `Plan ${org.plan} includes ${limits.seats} seats and ${seatsUsed} are taken`,
    );
  }

  if (replacing !== null) {
    await invitationRepo.revokeInvitation(orgId, replacing.id);
  }

  const invitations: Invitation[] = [];

  for (const invite of invites) {
    const token = randomToken(32);
    const invitation = await invitationRepo.insertInvitation(
      orgId,
      {
        orgId,
        email: invite.email,
        role: invite.role,
        expiresInDays: DEFAULT_EXPIRY_DAYS,
      },
      actor.userId,
      hashToken(token),
    );

    invitations.push(invitation);

    await emit("member.invited", {
      orgId,
      actorId: actor.userId,
      occurredAt: invitation.createdAt,
      email: invite.email,
      role: invite.role,
    });
  }

  return invitations;
}

/**
 * Accepting is keyed by the token, but the token alone is not enough: the
 * link is only good for the account whose email address it was sent to, so a
 * forwarded invite cannot be used by whoever it was forwarded to. Every other
 * check comes off the stored row, and nothing is written until all of them
 * have passed — a refused attempt leaves the invitation pending.
 */
export async function acceptInvitation(
  userId: UserId,
  input: AcceptInvitationTokenInput,
): Promise<Member> {
  const invitation = requireFound(
    await invitationRepo.findInvitationByTokenHash(hashToken(input.token)),
    "Invitation",
    "token",
  );

  const acceptedAt = toIsoTimestamp(new Date());

  if (invitation.revokedAt !== null) {
    throw new Error("That invitation has been revoked");
  }
  if (invitation.acceptedAt !== null) {
    throw new Error("That invitation has already been accepted");
  }
  if (invitation.expiresAt <= acceptedAt) {
    throw new Error("That invitation has expired");
  }

  const org = await orgRepo.findOrgById(invitation.orgId);
  if (!org || org.archivedAt !== null) {
    throw new Error("That invitation's organization no longer exists");
  }

  const user = requireFound(await userRepo.findUserById(userId), "User", userId);
  if (addressKey(user.email) !== addressKey(invitation.email)) {
    throw new Error("That invitation was sent to a different email address");
  }

  // A (org, user) pair only ever has one membership row, so a former member
  // is found here — archived — and gets that row back rather than a second.
  const previous = await memberRepo.findMembershipIncludingRemoved(
    invitation.orgId,
    userId,
  );

  // Claims the invitation; from here on it is used up and cannot be replayed.
  await invitationRepo.markInvitationAccepted(
    invitation.orgId,
    invitation.id,
    acceptedAt,
  );

  // Already a current member: nothing to create and no new seat to count.
  if (previous !== null && previous.archivedAt === null) return previous;

  const member =
    previous === null
      ? await memberRepo.insertMember(
          invitation.orgId,
          userId,
          invitation.role,
          invitation.invitedBy,
          acceptedAt,
        )
      : await memberRepo.restoreMember(
          invitation.orgId,
          previous.id,
          invitation.role,
          invitation.invitedBy,
          acceptedAt,
        );

  await emit("member.joined", {
    ...envelope(invitation.orgId, userId),
    memberId: member.id,
    userId,
    role: member.role,
  });

  return member;
}

export async function revokeInvitation(
  actor: Actor,
  invitationId: InvitationId,
): Promise<Invitation> {
  assertCan(actor, "member:invite", orgResource(actor.orgId));
  return invitationRepo.revokeInvitation(actor.orgId, invitationId);
}

/**
 * Re-issuing does not reuse the row: the original is revoked and replaced so
 * the audit trail keeps both, and the old link stops working immediately. The
 * replacement goes to the same address with the same role and a fresh 14 days.
 *
 * An invitation that has run out can be re-sent — that is the usual reason to
 * re-send one — but one that was accepted or revoked is closed for good.
 */
export async function resendInvitation(
  actor: Actor,
  invitationId: InvitationId,
): Promise<Invitation> {
  assertOrgScope(actor, actor.orgId);
  assertCan(actor, "member:invite", orgResource(actor.orgId));

  const stored = await invitationRepo.findInvitationById(
    actor.orgId,
    invitationId,
  );
  const previous = requireFound(
    stored && stored.acceptedAt === null && stored.revokedAt === null
      ? stored
      : null,
    "Invitation",
    invitationId,
  );

  const [invitation] = await issueInvitations(
    actor,
    actor.orgId,
    [{ email: previous.email, role: previous.role as InviteRequest["role"] }],
    previous,
  );

  if (!invitation) throw new Error("Invitation was not created");
  return invitation;
}
'''
open(p,'w').write(head+body)
EOF

