import assert from "node:assert/strict";
import { eq } from "drizzle-orm";
import { getDb, sessions, invitations, notificationPreferences } from "@/server/db";
import { runMigrations } from "@/server/db/migrate";
import { hashToken } from "@/lib/hash";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as sessionRepo from "@/server/repositories/session-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as inv from "@/server/services/invitation-service";
import * as memberService from "@/server/services/member-service";
import * as orgService from "@/server/services/organization-service";
import * as sessionService from "@/server/services/session-service";
import { notify, listNotifications } from "@/server/services/notification-service";
import { listDigestRecipients } from "@/server/services/digest-service";
import { registerUsageListeners } from "@/server/services/usage-service";

const rejects = async (p: Promise<unknown>, re?: RegExp) => {
  try { await p; } catch (e) { if (re) assert.match((e as Error).message, re); return (e as Error).message; }
  assert.fail("expected rejection");
};

async function tenant(slug: string, plan: "free" | "starter" | "growth", extra: string[] = []) {
  const owner = await userRepo.insertUser({ email: `owner@${slug}.test`, name: "o", passwordHash: "x" });
  const org = await orgRepo.insertOrg({ name: slug, slug, plan }, owner.id);
  await subscriptionRepo.insertSubscription(org.id, plan, "monthly");
  await memberRepo.insertMember(org.id, owner.id, "owner", null);
  const users = [];
  for (const e of extra) {
    const u = await userRepo.insertUser({ email: e, name: e, passwordHash: "x" });
    await memberRepo.insertMember(org.id, u.id, "member", null);
    users.push(u);
  }
  await usageRepo.recomputeUsage(org.id);
  return { org, owner, users, actor: { userId: owner.id, orgId: org.id, role: "owner" as const } };
}

async function seedInvite(orgId: any, email: string, role: any, by: any, token: string, days = 14) {
  return invitationRepo.insertInvitation(orgId, { orgId, email, role, expiresInDays: days }, by, hashToken(token));
}

async function main() {
  await runMigrations(process.env.TASKFLOW_DB_PATH!);
  registerUsageListeners();

  // --- 3: 14 days
  const t = await tenant("alpha", "growth", ["m1@alpha.test"]);
  const i1 = await inv.inviteMember(t.actor, { orgId: t.org.id, email: "New@Alpha.test", role: "admin" });
  const days = (Date.parse(i1.expiresAt) - Date.now()) / 86400000;
  assert.ok(days > 13.99 && days < 14.01, `days ${days}`);

  // --- 5: duplicates
  await rejects(inv.inviteMember(t.actor, { orgId: t.org.id, email: "new@alpha.TEST", role: "member" }), /pending/);
  await rejects(inv.inviteMember(t.actor, { orgId: t.org.id, email: "M1@alpha.test", role: "member" }), /member/);
  await rejects(inv.inviteMembers(t.actor, { orgId: t.org.id, invites: [
    { email: "fresh@alpha.test", role: "member" }, { email: "x@alpha.test", role: "member" }, { email: "X@alpha.test", role: "member" } ] }), /more than once/);
  assert.equal(await invitationRepo.countPendingInvitations(t.org.id), 1);

  // --- 7: resend keeps role, withdraws old
  const i2 = await inv.resendInvitation(t.actor, i1.id);
  assert.equal(i2.role, "admin"); assert.equal(i2.email, "New@Alpha.test");
  assert.equal(await invitationRepo.countPendingInvitations(t.org.id), 1);
  assert.notEqual((await invitationRepo.findInvitationById(t.org.id, i1.id))!.revokedAt, null);
  await rejects(inv.resendInvitation(t.actor, i1.id));

  // resend expired
  const exp = await seedInvite(t.org.id, "late@alpha.test", "viewer", t.owner.id, "e".repeat(32), -3);
  assert.equal(await invitationRepo.countPendingInvitations(t.org.id), 1);
  assert.equal((await invitationRepo.listPendingInvitations(t.org.id)).length, 1);
  const re = await inv.resendInvitation(t.actor, exp.id);
  assert.equal(re.role, "viewer");
  assert.equal(await invitationRepo.countPendingInvitations(t.org.id), 2);

